sys_script_client.script:
function onLoad() {
    // MSSTRESURY-160: To notify user that someone is already working on the task before the user works on it.
    // MSSTRESURY-295: Implementation - Allow user to update callback maker task status to be pending
    var taskType = g_form.getValue('task_type');
    if (taskType != 'Callback') {
        g_form.removeOption('state', '7');
    }
    if (taskType === 'Callback' || taskType === 'Callback Checker') {
        // Show comment
        g_form.setValue('comments', g_form.getValue('comments_last_value'));
    }

    var userID = g_user.userID;
    var assignedUser = g_form.getValue('assigned_to');

    // MSSTRESURY-452: Prevent same user from being assigned to both maker and checker task
    if (g_scratchpad.taskAlreadyAssignTo && g_scratchpad.taskAlreadyAssignTo[userID] && !assignedUser && g_scratchpad.flag) {
        g_form.addErrorMessage("Same user can't be assigned to both maker and checker task.");
    }

    // MSSTRESURY-756
    // Check if the user is a manager
    if (g_scratchpad.isManager) {
        g_form.addInfoMessage("Please Click 'Assign to me' to work on this task.");
        return;
    }

    // If task is Unassigned: Lock all fields
    if (assignedUser === '' && g_scratchpad.flag) {
        g_form.addInfoMessage("Please Click 'Assign to me' to work on this task.");
    }
}
